{"code": "# Let me build a proper maze model and try BFS
# Grid indices: rows 0-10, cols 0-10
# Map actual coords to grid indices
row_map = {v: i for i, v in enumerate([16, 19, 22, 25, 28, 31, 34, 37, 40, 43, 46])}
col_map = {v: i for i, v in enumerate([16, 19, 22, 25, 28, 31, 34, 37, 40, 43, 46])}

# Build the grid
grid_data = {}
for node in current_frame.segmentation['nodes'][1:]:
    b = node['boundary']
    rows = [p[0] for p in b]
    cols = [p[1] for p in b]
    center = (sum(rows)//len(rows), sum(cols)//len(cols))
    grid_data[center] = node['color']

# Create 11x11 grid
maze = [['.' for _ in range(11)] for _ in range(11)]
player_pos = None
goal_pos = None

for (r, c), color in grid_data.items():
    if r == 63 or c == 63:
        continue  # skip HUD
    if r in row_map and c in col_map:
        ri, ci = row_map[r], col_map[c]
        maze[ri][ci] = color
        if color == 'b':
            player_pos = (ri, ci)
        elif color == 'N':
            goal_pos = (ri, ci)

print(f"Player at grid: {player_pos}, Goal at grid: {goal_pos}")
print("\nMaze grid:")
for i, row in enumerate(maze):
    print(f"  {i}: {''.join(row)}")

# BFS to find path - assume we can move through all non-B cells
from collections import deque

def bfs(start, goal, maze):
    rows = len(maze)
    cols = len(maze[0])
    queue = deque([(start, [])])
    visited = {start}

    while queue:
        (r, c), path = queue.popleft()
        if (r, c) == goal:
            return path
        for dr, dc, move in [(-1, 0, 'UP'), (1, 0, 'DOWN'), (0, -1, 'LEFT'), (0, 1, 'RIGHT')]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
                if maze[nr][nc] != 'B':  # Can't walk through black walls
                    visited.add((nr, nc))
                    queue.append(((nr, nc), path + [move]))
    return None

path = bfs(player_pos, goal_pos, maze)
print(f"\nPath found: {path}")
if path:
    print(f"Path length: {len(path)}")
"}

